create table if not exists bar_layout (
 id smallint primary key check (id=1),
 layout jsonb not null,
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now(),
 updated_by uuid references users(id) on delete set null
);
insert into bar_layout (id,layout) values (1,'{"defaultSlotId":"bar-8","slots":[{"id":"bar-1","occupantId":"daria","x":50,"y":50,"scale":1},{"id":"bar-2","occupantId":"grigory","x":50,"y":50,"scale":1},{"id":"bar-3","occupantId":"maria","x":50,"y":50,"scale":1},{"id":"bar-4","occupantId":"arsenich","x":50,"y":50,"scale":1},{"id":"bar-5","occupantId":"online","x":50,"y":50,"scale":1},{"id":"bar-6","occupantId":"oleg","x":50,"y":50,"scale":1},{"id":"bar-7","occupantId":"timofey","x":50,"y":50,"scale":1},{"id":"bar-8","occupantId":"veronika","x":50,"y":50,"scale":1},{"id":"bar-9","occupantId":"news","x":50,"y":50,"scale":1},{"id":"bar-10","occupantId":"broadcasts","x":50,"y":50,"scale":1}],"profiles":{"daria":{"name":"Дарья","role":"Официантка","description":"Открытая и любопытная. Легко знакомится с людьми и не боится задавать вопросы.","avatar":"/bar/cards/daria-avatar-v2.webp","composition":"/bar/cards/daria-composition-v1.webp"},"grigory":{"name":"Григорий","role":"Заливщик льда","description":"Шустрый и хитрый, за словом в карман не лезет. Любит поддеть собеседника и проверить его на прочность.","avatar":"/bar/cards/grigory-avatar-v2.webp","composition":"/bar/cards/grigory-composition-v1.webp"},"maria":{"name":"Мария","role":"Официантка","description":"Общительная и наблюдательная. Любит подшутить, но всегда знает, когда стоит выслушать.","avatar":"/bar/cards/avatar-v2.webp","composition":"/bar/cards/maria-composition-v1.webp"},"arsenich":{"name":"Арсенич","role":"Работник стадиона","description":"Спокойный и рассудительный. Говорит прямо, замечает больше, чем показывает, и помогает без лишних слов.","avatar":"/bar/cards/arsenich-avatar-v2.webp","composition":"/bar/cards/arsenich-composition-v1.webp"},"online":{"name":"Играть онлайн","role":"","description":"Найди соперников или пригласи знакомого игрока.","avatar":null,"composition":"/bar/cards/online-terminal-v1.webp"},"oleg":{"name":"Олег","role":"Охранник","description":"","avatar":null,"composition":null},"timofey":{"name":"Тимофей","role":"Работник стадиона","description":"","avatar":null,"composition":null},"veronika":{"name":"Вероника","role":"Управляющая баром","description":"","avatar":null,"composition":null},"news":{"name":"Газеты на стойке","role":"","description":"","avatar":null,"composition":null},"broadcasts":{"name":"Трансляции","role":"","description":"Смотри хоккейные матчи.","avatar":null,"composition":null}}}'::jsonb) on conflict (id) do nothing;
